import ghidra.app.script.GhidraScript;
import ghidra.app.cmd.function.CreateFunctionCmd;
import ghidra.program.model.address.*;
import ghidra.program.model.data.*;
import ghidra.program.model.pcode.JumpTable;
import ghidra.program.model.symbol.*;
import java.io.*;
import java.util.*;
public class N3DRecoverRemainingSwitches extends GhidraScript {
 public void run() throws Exception {
  try(PrintWriter p=new PrintWriter(getScriptArgs()[0])){
   p.println("owner\tbranch\ttable\tindex\ttarget");
   for(String[] s:new String[][]{{"1000:d32e","1000:d35b","1000:d360","8"},{"1000:6f5c","1000:6f90","1000:6f95","20"},{"1008:18b4","1008:1918","1008:191d","13"}}){
    var f=getFunctionAt(toAddr(s[0]));var branch=toAddr(s[1]);var table=toAddr(s[2]);int n=Integer.parseInt(s[3]);var targets=new ArrayList<Address>();
    for(int i=0;i<n;i++){
     var a=toAddr(String.format("%s:%04x",s[0].substring(0,4),getShort(table.add(2*i))&0xffff));
     disassemble(a);if(!targets.contains(a))targets.add(a);
     currentProgram.getListing().getInstructionAt(branch).addOperandReference(0,a,RefType.COMPUTED_JUMP,SourceType.USER_DEFINED);
     p.println(s[0]+"\t"+s[1]+"\t"+s[2]+"\t"+i+"\t"+a);
    }
    new JumpTable(branch,targets,true,0).writeOverride(f);CreateFunctionCmd.fixupFunctionBody(currentProgram,f,monitor);
    createData(table,new ArrayDataType(WordDataType.dataType,n,2));
    println("RECOVERED_BOUNDED_SWITCH "+s[0]+" table_words="+n);
   }
   var a=toAddr("1008:4e14");createData(a,new ArrayDataType(WordDataType.dataType,8,2));
  }
 }
}

