import ghidra.app.script.GhidraScript;
import java.nio.file.*;
import java.io.*;
import java.util.*;
public class N3DDefineClassStrings extends GhidraScript {
 public void run() throws Exception {
  Set<String> seen=new HashSet<>();
  try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){
   out.println("address\ttext\tstatus");
   for(int arg=1;arg<getScriptArgs().length;arg++){
    var lines=Files.readAllLines(Paths.get(getScriptArgs()[arg]));
    for(String line:lines.subList(1,lines.size())){
     String[] c=line.split("\t");String addr=c[2],text=c[3];
     if(!text.matches("C[A-Za-z0-9_]+")||!seen.add(addr))continue;
     var a=toAddr(addr);boolean matches=true;
     for(int i=0;i<text.length();i++)if((getByte(a.add(i))&255)!=text.charAt(i))matches=false;
     if(getByte(a.add(text.length()))!=0)matches=false;
     if(!matches)throw new Exception("String evidence differs at "+addr);
     if(currentProgram.getListing().getInstructionContaining(a)!=null){out.println(addr+"\t"+text+"\tinstruction_conflict_requires_review");continue;}
     var data=getDataAt(a);if(data!=null&&data.isDefined()){out.println(addr+"\t"+text+"\talready_defined");continue;}
     createAsciiString(a);out.println(addr+"\t"+text+"\tdefined_from_descriptor_pointer");
    }
   }
  }
 }
}
